<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {storeToday} from '../time'
import {estimateDays,initialEstimateMonth,estimateDeductions,type PayPlanEstimateResult} from '../fullAttendanceEstimate'
import {validRule,validMonth} from '../payrollUi'
import {WorkforceApiError} from '../api'
import type {PayRule,CpfProfile} from '../payrollTypes'
import PayBreakdownSummary from './PayBreakdownSummary.vue'
const props=defineProps<{companyId:string;employeeId:string;effectiveFrom:string;initialMonth?:string;rule:PayRule;cpf:Omit<CpfProfile,'citizenship'>&{citizenship:string};cdac:{status:string;reference:string}}>()
defineEmits<{(e:'edit-facts'):void}>()
const {api,current,store,english,message,issue}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const month=ref(initialEstimateMonth(props.effectiveFrom,props.initialMonth||'',storeToday())),days=ref<number|''>(estimateDays(month.value,props.rule.generation?.workingWeekdays)),hours=ref(props.rule.dayHours),result=ref<PayPlanEstimateResult|null>(null),pending=ref(false),error=ref('')
let revision=0;onBeforeUnmount(()=>revision++)
const signature=computed(()=>JSON.stringify([store.value,props.companyId,props.employeeId,props.rule,props.cpf,props.cdac,props.effectiveFrom,month.value,days.value,hours.value]))
watch(signature,()=>{revision++;result.value=null;pending.value=false;error.value=''},{flush:'sync'})
watch(()=>[month.value,JSON.stringify(props.rule.generation?.workingWeekdays)],()=>{days.value=estimateDays(month.value,props.rule.generation?.workingWeekdays)})
watch(()=>props.rule.dayHours,v=>{hours.value=v})
const factsReady=computed(()=>!!props.cdac.status&&['citizen','spr','foreign'].includes(props.cpf.citizenship)&&(props.cpf.citizenship==='foreign'||!!props.cpf.birthDate)&&(props.cpf.citizenship!=='spr'||!!props.cpf.prDate))
const ready=computed(()=>factsReady.value&&props.companyId&&props.employeeId&&validMonth(month.value)&&validRule(props.rule)&&!!props.cdac.status&&['citizen','spr','foreign'].includes(props.cpf.citizenship)&&Number.isInteger(Number(days.value))&&Number(days.value)>0&&Number(days.value)<=31&&Number(hours.value)>0&&Number(hours.value)<=24)
async function calculate(){if(!ready.value||pending.value)return;const rev=++revision,owner=store.value;result.value=null;error.value='';pending.value=true;try{const value=await api().post<PayPlanEstimateResult>('/pay-plan-estimate',{companyId:props.companyId,employeeId:props.employeeId,month:month.value,rule:props.rule,cpf:props.cpf,cdac:props.cdac,days:Number(days.value),dayHours:hours.value});if(current()&&owner===store.value&&revision===rev)result.value=value}catch(e){if(current()&&revision===rev)error.value=e instanceof WorkforceApiError&&issue(e.code)!==e.code?issue(e.code):message(e)}finally{if(current()&&revision===rev)pending.value=false}}
</script>
<template><section class="wf-section pay-plan-estimate" :aria-label="x('满勤预计到手','Full-attendance estimate')"><h3>{{x('满勤预计到手','Estimated full-attendance take-home')}}</h3><p class="wf-hint">{{x('按完整月满勤、全勤条件均满足测算，含已配置月津贴；不含加班、请假或本月临时调整。保存或审批方案后，正式工资仍按核准资料办理。','Assumes a full month, all attendance conditions met and configured monthly allowances. Excludes overtime, leave and one-off adjustments. Actual payroll uses approved facts after the plan becomes effective.')}}</p><div class="wf-grid"><label>{{x('测算月份','Estimate month')}}<input v-model="month" type="month"/></label><label>{{x('满勤工作日数','Full-attendance working days')}}<input v-model.number="days" type="number" min="1" max="31" step="1"/></label><label>{{x('每日普通工时','Ordinary hours per day')}}<input v-model="hours" type="number" min="0.01" max="24" step="0.01"/></label></div><p v-if="!props.rule.generation?.workingWeekdays?.length" class="wf-hint">{{x('未配置标准工作星期，请填写满勤天数；不按日历天数猜算。','No standard weekdays configured. Enter working days explicitly.')}}</p><p v-if="!factsReady" class="wf-hint">{{x('先核对员工身份、出生／PR资料及CDAC适用资格，才能预计到手金额。','Review citizenship, birth / PR dates and CDAC eligibility before estimating take-home pay.')}}</p><button v-if="!factsReady" type="button" @click="$emit('edit-facts')">{{x('补齐必要资料','Complete required facts')}}</button><button type="button" :disabled="!ready||pending" @click="calculate">{{pending?x('测算中…','Calculating…'):x('测算满勤所得','Estimate full-attendance pay')}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="result"><div class="wf-pay-final"><strong>{{x('预计到手','Estimated take-home')}} SGD {{result.breakdown.net}}</strong><span>{{x('预计应发','Estimated gross')}} {{result.breakdown.gross}}</span><span>{{x('员工扣款合计','Employee deductions')}} {{estimateDeductions(result.breakdown)??'—'}}</span><span>{{x('公司总成本（个人估算）','Company cost (individual estimate)')}} {{result.breakdown.employerCost}}</span></div><p class="wf-hint">{{result.month}} · {{result.days}} {{x('天','days')}} × {{result.dayHours}} h · {{x('政策版本','Policy')}} {{result.policy}}<br/>{{x('完整月假设，不按入职生效日折算；全勤奖是假设符合，尚未核准。SDL保留个人精度，公司实缴按全公司汇总舍入。此结果不确认工资、不付款。','Full-month assumption, without hire-date proration. Attendance bonus eligibility is assumed, not approved. SDL retains individual precision; company liability uses company aggregation. This estimate neither confirms nor pays wages.')}}</p><details><summary>{{x('查看收入、扣款和公司承担依据','View income, deductions and company costs')}}</summary><p>{{x('基本工资依据','Basic pay basis')}}: {{props.rule.basis==='monthly'?x('整月月薪','Full monthly salary'):props.rule.basis==='daily'?result.days+x('天 × 日薪','days × day rate'):(result.workSeconds/3600).toFixed(2)+x('小时 × 时薪','hours × hourly rate')}} · SGD {{props.rule.rate}}</p><p>{{x('CPF／SDL／CDAC依据：所选月份、员工身份与年龄及上列生效政策；不是固定扣款比例。','CPF / SDL / CDAC: selected month, employee category and age, and the effective policy above. No fixed deduction percentage is assumed.')}}</p><PayBreakdownSummary :value="result.breakdown" details business-labels/><ul><li v-for="item in result.breakdown.items.filter(i=>!['basic','overtime','employee_cpf','employer_cpf','sdl','cdac'].includes(i.kind))" :key="item.label+item.kind">{{item.label}} · SGD {{item.amount}} · {{item.kind==='ow_attendance'?x('假设全勤条件满足','Attendance conditions assumed met'):x('按完整月配置金额','Configured full-month amount')}}</li></ul></details></template></section></template>
<style scoped>.pay-plan-estimate{min-width:0;overflow-wrap:anywhere}</style>
